#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <Servo.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);
Servo dispenserServo;
const String MASTER_PIN = "7788";
String inputPin = "";

void setup() {
  lcd.init();
  lcd.backlight();
  dispenserServo.attach(10);
  dispenserServo.write(0); // Chute closed
  lcd.setCursor(0, 0);
  lcd.print("MONSTER ATM: PIN");
}

void dispenseReward() {
  lcd.clear();
  lcd.print("ACCESS GRANTED!");
  dispenserServo.write(90); // Open chute
  delay(2000);
  dispenserServo.write(0);  // Close chute
  lcd.clear();
  lcd.print("MONSTER ATM: PIN");
}
